package com.aistock.market.support;
import com.aistock.common.marketrefs.*;import com.aistock.common.marketrefs.MarketReferenceRecords.*;import java.time.Clock;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class ReferenceScannerMysqlTest {
 static final String V="11111111-1111-1111-1111-111111111111";JdbcTemplate j;Source source=new Source("snapshots","快照记录","reference_test_records",List.of("version_id"),List.of("payload","extra_json"));
 @BeforeEach void init(){j=new MarketDatabaseFixture().jdbc();j.execute("create table if not exists reference_test_records(id int primary key,version_id char(36) collate utf8mb4_bin null,payload longtext null,extra_json json null) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_bin");j.update("delete from reference_test_records");}
 @AfterEach void cleanup(){if(j!=null)j.execute("drop table if exists reference_test_records");}
 ReferenceScanner scanner(){return new ReferenceScanner(j.getDataSource(),"prediction",List.of(source),Clock.systemUTC());}
 @Test void countsExactUuidOncePerRowAndLeavesDataUntouched(){j.update("insert into reference_test_records values(1,?,?,?)",V,"{\"v\":\""+V+"\"}","[\""+V+"\"]");j.update("insert into reference_test_records values(2,null,?,null)","[{\"nested\":[\""+V+"\"]}]");j.update("insert into reference_test_records values(3,null,?,null)","{\"v\":\"prefix-"+V+"-suffix\"}");var before=j.queryForList("select * from reference_test_records order by id").toString();var result=scanner().scan(V);assertEquals("COMPLETE",result.state());assertEquals("2",result.groups().get(0).rows());assertEquals(before,j.queryForList("select * from reference_test_records order by id").toString());}
 @Test void damagedJsonIsUnknownNotZero(){j.update("insert into reference_test_records values(1,null,'broken',null)");var g=scanner().scan(V).groups().get(0);assertEquals("REFERENCE_JSON_INVALID",g.reasonCode());assertNull(g.rows());}
 @Test void boundedRowsAndExactByteBoundary(){for(int i=1;i<=3;i++)j.update("insert into reference_test_records values(?,null,'{}',null)",i);var limited=new ReferenceScanner(j.getDataSource(),"prediction",List.of(source),Clock.systemUTC(),new ReferenceScanner.Limits(2,32));assertEquals("REFERENCE_ROW_LIMIT",limited.scan(V).groups().get(0).reasonCode());j.update("delete from reference_test_records");j.update("insert into reference_test_records values(1,null,?,null)","\""+"x".repeat(30)+"\"");assertEquals("COMPLETE",limited.scan(V).state());j.update("update reference_test_records set payload=? where id=1","\""+"x".repeat(31)+"\"");assertEquals("REFERENCE_JSON_LIMIT",limited.scan(V).groups().get(0).reasonCode());}
 @Test void emptyIsKnownZeroWhileMissingTableIsUnknown(){assertEquals("0",scanner().scan(V).groups().get(0).rows());var absent=new Source("absent","缺失表","reference_test_absent",List.of("version_id"),List.of());var g=new ReferenceScanner(j.getDataSource(),"prediction",List.of(absent),Clock.systemUTC()).scan(V).groups().get(0);assertNull(g.rows());assertEquals("REFERENCE_QUERY_UNAVAILABLE",g.reasonCode());}
}
